%% plotFzVsThx_thxOnlySweep.m
% Uses the dedicated thx-only characterization sweep (rows 151-200 of
% comsol_sweep_combined300_results.txt, generated by
% dedicatedSingleAxisSweeps.m: thx swept with rx=ry=rz=thy=thz=0 held
% exactly) to isolate the pure tilt-vs-Fz relationship, free of the
% scatter from other DOF that muddies the full6D LHS dataset.
%
% Compares: simulation, fringing-capacitance model (trapElectrode1Model),
% and the parallel-plate model (theta-independent by construction, so
% it should show up as a flat line -- this is the clean test of whether
% the fringing model actually earns its tilt terms).

clear; clc;
scriptDir = fileparts(mfilename('fullpath'));
addpath(scriptDir);

data = parseComsolResults(fullfile(scriptDir, 'comsol_sweep_combined300_results.txt'));
thxBlock = data(151:200, :);

if any(thxBlock.rx ~= 0) || any(thxBlock.ry ~= 0) || any(thxBlock.rz ~= 0) || ...
   any(thxBlock.thy ~= 0) || any(thxBlock.thz ~= 0)
    error('Expected rows 151-200 to be the thx-only block (all other DOF = 0). Check row indexing.');
end

V = 30;
n = height(thxBlock);
U = V*ones(n,1);

%% Fringing-capacitance model
[~, ~, Fz_fringe] = trapElectrode1Model(thxBlock.rx, thxBlock.ry, thxBlock.rz, ...
    thxBlock.thx, thxBlock.thy, thxBlock.thz, U);

%% Parallel-plate model (same A as fit on the full6D dataset, applied here at rz=0)
load(fullfile(scriptDir, 'full6D_energyData.mat'));
d0 = 15e-6; eps0 = 8.854e-12; eps_r = 1;
predictor_full = eps_r*eps0*30^2 ./ (2*(d0-rz).^2);
A_fit = (predictor_full' * Fz_MST) / (predictor_full' * predictor_full);
Fz_pp = A_fit * eps_r*eps0*V^2/(2*(d0-0)^2) * ones(n,1);   % rz=0 throughout this block -> constant

%% R^2 (against this thx-only block's own simulation data)
r2fun = @(y,yhat) 1 - sum((y-yhat).^2)/sum((y-mean(y)).^2);
r2_fringe = r2fun(thxBlock.Fz, Fz_fringe);
r2_pp = r2fun(thxBlock.Fz, Fz_pp);
fprintf('thx-only sweep (n=%d): Fringing model R^2 = %.4f, Parallel-plate model R^2 = %.4f\n', n, r2_fringe, r2_pp);
fprintf('thx range: [%.4f, %.4f] deg\n', min(thxBlock.thx), max(thxBlock.thx));
fprintf('Fz sim range: [%.4e, %.4e] N (peak-to-peak %.4e N)\n', min(thxBlock.Fz), max(thxBlock.Fz), range(thxBlock.Fz));

%% Plot
figure('Color','w','Name','Fz vs thx: dedicated single-axis sweep', 'Position',[50 50 800 550]);
hold on; grid on;
scatter(thxBlock.thx, thxBlock.Fz, 30, 'k', 'filled', 'DisplayName', 'Simulation');
scatter(thxBlock.thx, Fz_fringe, 30, 'r', 'filled', 'DisplayName', sprintf('Fringing model (R^2=%.4f)', r2_fringe));
plot(thxBlock.thx, Fz_pp, 'b-', 'LineWidth', 2, 'DisplayName', sprintf('Parallel-plate model (R^2=%.4f)', r2_pp));
xlabel('\theta_x [deg]'); ylabel('Fz [N]');
title('Fz vs \theta_x (dedicated thx-only sweep, rx=ry=rz=\theta_y=\theta_z=0)');
legend('Location','best');

exportgraphics(gcf, fullfile(scriptDir, 'Fz_vs_thx_thxOnlySweep.png'));
fprintf('Saved plot to Fz_vs_thx_thxOnlySweep.png\n');
